changeSet.sql:
CREATE OR REPLACE TRIGGER trg_integridad_hallazgo_append
BEFORE UPDATE OR DELETE ON integridad_hallazgo
BEGIN
    RAISE_APPLICATION_ERROR(-20006, 'Un hallazgo de un informe de integridad es inmutable');
END;

CREATE OR REPLACE TRIGGER trg_integridad_informe_append
BEFORE UPDATE OR DELETE ON integridad_informe
FOR EACH ROW
BEGIN
    IF DELETING THEN
        RAISE_APPLICATION_ERROR(-20007, 'Un informe de integridad no se borra: se conserva con la misma retencion que el resto del historico');
    END IF;

    IF :OLD.status <> 'EN_CURSO' THEN
        RAISE_APPLICATION_ERROR(-20007, 'El informe de integridad ya esta sellado y es inmutable');
    END IF;

    IF :NEW.status NOT IN ('COMPLETADO', 'FALLIDO') THEN
        RAISE_APPLICATION_ERROR(-20007, 'La unica modificacion admitida sobre un informe en curso es su sellado a COMPLETADO o FALLIDO');
    END IF;

    IF :NEW.executed_at <> :OLD.executed_at
       OR NVL(:NEW.executed_by, -1) <> NVL(:OLD.executed_by, -1)
       OR NVL(:NEW.scope_date_from, DATE '0001-01-01') <> NVL(:OLD.scope_date_from, DATE '0001-01-01')
       OR NVL(:NEW.scope_date_to, DATE '0001-01-01') <> NVL(:OLD.scope_date_to, DATE '0001-01-01') THEN
        RAISE_APPLICATION_ERROR(-20007, 'El sellado de un informe de integridad no puede alterar su ejecutor, su instante ni su alcance');
    END IF;
END;

DECLARE
    v_admin     NUMBER;
    v_empleado  NUMBER;
    v_tecnico   NUMBER;
    v_oficina   NUMBER;
    v_sala      NUMBER;
    v_categoria NUMBER;
    v_inc_a     NUMBER;
    v_inc_b     NUMBER;
    v_inc_c     NUMBER;
    v_inc_d     NUMBER;
    v_now       TIMESTAMP := SYS_EXTRACT_UTC(SYSTIMESTAMP);
    v_t0        TIMESTAMP;
    v_t1        TIMESTAMP;
    v_t2        TIMESTAMP;
    v_t3        TIMESTAMP;
    v_t4        TIMESTAMP;
    v_h0        VARCHAR2(64 CHAR);
    v_h1        VARCHAR2(64 CHAR);
    v_h2        VARCHAR2(64 CHAR);
    v_h3        VARCHAR2(64 CHAR);
    v_h4        VARCHAR2(64 CHAR);
    v_falsa     VARCHAR2(64 CHAR);
    v_asientos  NUMBER;
    v_estado    VARCHAR2(20 CHAR);

    c_admin_nom    CONSTANT VARCHAR2(150 CHAR) := 'Oraculo TSK-061 Administrador';
    c_empleado_nom CONSTANT VARCHAR2(150 CHAR) := 'Oraculo TSK-061 Empleado';
    c_tecnico_nom  CONSTANT VARCHAR2(150 CHAR) := 'Oraculo TSK-061 Tecnico';
    c_resolucion   CONSTANT VARCHAR2(500 CHAR) := 'Comentario de resolucion del oraculo TSK-061: se reparo la averia reportada';
    c_descripcion  CONSTANT VARCHAR2(500 CHAR) := 'Incidencia del oraculo TSK-061 para verificar las invariantes de integridad del historico';

    FUNCTION huella(p_semilla VARCHAR2) RETURN VARCHAR2 IS
        l_hash VARCHAR2(64 CHAR);
    BEGIN
        SELECT RAWTOHEX(STANDARD_HASH(p_semilla, 'SHA256')) INTO l_hash FROM dual;
        RETURN l_hash;
    END huella;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER, p_terminal VARCHAR2) IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, p_terminal, 'Y');
    END sembrar_estado;

    FUNCTION oficina_oraculo RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT office_id INTO l_id FROM cat_oficina WHERE office_code = 'ORA61';
        UPDATE cat_oficina SET is_active = 'Y' WHERE office_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_oficina (office_code, office_name, city, is_active)
                 VALUES ('ORA61', 'Oficina del oraculo TSK-061', 'Madrid', 'Y')
              RETURNING office_id INTO l_id;
            RETURN l_id;
    END oficina_oraculo;

    FUNCTION sala_oraculo(p_office_id NUMBER, p_created_by NUMBER) RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT room_id INTO l_id FROM cat_sala WHERE room_code = 'ORA61-SALA-01';
        UPDATE cat_sala SET is_active = 'Y' WHERE room_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_sala (room_code, room_name, office_id, is_active, created_by)
                 VALUES ('ORA61-SALA-01', 'Sala del oraculo TSK-061', p_office_id, 'Y', p_created_by)
              RETURNING room_id INTO l_id;
            RETURN l_id;
    END sala_oraculo;

    FUNCTION categoria_oraculo RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT category_id INTO l_id FROM cat_categoria_incidencia WHERE category_code = 'CLIMATIZACION';
        UPDATE cat_categoria_incidencia SET is_active = 'Y' WHERE category_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_categoria_incidencia (category_code, category_name, display_order, is_active)
                 VALUES ('CLIMATIZACION', 'Climatizacion oraculo TSK-061', 961, 'Y')
              RETURNING category_id INTO l_id;
            RETURN l_id;
    END categoria_oraculo;

    FUNCTION alta_incidencia(p_ref VARCHAR2, p_reporter NUMBER, p_created TIMESTAMP) RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        INSERT INTO incidencia (reference_code, room_id, category_id,
                                room_name_snapshot, office_name_snapshot, category_name_snapshot,
                                description, status, reported_by, created_at, status_changed_at)
             VALUES (p_ref, v_sala, v_categoria,
                     'Sala del oraculo TSK-061', 'Oficina del oraculo TSK-061', 'Climatizacion oraculo TSK-061',
                     c_descripcion, 'ABIERTA', p_reporter, p_created, p_created)
          RETURNING incident_id INTO l_id;
        RETURN l_id;
    END alta_incidencia;

    PROCEDURE asentar(p_inc NUMBER, p_entry_type VARCHAR2, p_from VARCHAR2, p_to VARCHAR2,
                      p_tech NUMBER, p_tech_name VARCHAR2,
                      p_actor NUMBER, p_actor_name VARCHAR2, p_changed_at TIMESTAMP,
                      p_res_ref NUMBER, p_prev_hash VARCHAR2, p_hash VARCHAR2) IS
    BEGIN
        INSERT INTO incidencia_historico (incident_id, entry_type, from_status, to_status,
                                          assigned_technician_id, assigned_technician_name,
                                          actor_user_id, actor_display_name, changed_at,
                                          resolution_comment_ref, previous_entry_hash, entry_hash)
             VALUES (p_inc, p_entry_type, p_from, p_to,
                     p_tech, p_tech_name,
                     p_actor, p_actor_name, p_changed_at,
                     p_res_ref, p_prev_hash, p_hash);
    END asentar;

    PROCEDURE exigir(p_vista VARCHAR2, p_inc NUMBER, p_esperadas NUMBER, p_codigo NUMBER, p_caso VARCHAR2) IS
        l_n NUMBER;
    BEGIN
        EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM ' || p_vista || ' WHERE incident_id = :1' INTO l_n USING p_inc;
        IF l_n <> p_esperadas THEN
            RAISE_APPLICATION_ERROR(p_codigo, 'ORACULO AC-HIST-06 ' || p_caso || ': la vista ' || p_vista ||
                ' devuelve ' || l_n || ' filas para la incidencia ' || p_inc || ' y se esperaban ' || p_esperadas);
        END IF;
    END exigir;
BEGIN
    v_t0 := v_now - INTERVAL '5' HOUR;
    v_t1 := v_now - INTERVAL '4' HOUR;
    v_t2 := v_now - INTERVAL '3' HOUR;
    v_t3 := v_now - INTERVAL '2' HOUR;
    v_t4 := v_now - INTERVAL '1' HOUR;

    sembrar_rol('EMPLEADO', 'Empleado', 911);
    sembrar_rol('TECNICO_MANTENIMIENTO', 'Tecnico de mantenimiento', 912);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 913);

    sembrar_estado('ABIERTA',  'Abierta',  1, 'N');
    sembrar_estado('EN_CURSO', 'En curso', 2, 'N');
    sembrar_estado('RESUELTA', 'Resuelta', 3, 'N');
    sembrar_estado('CERRADA',  'Cerrada',  4, 'Y');

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES (c_admin_nom, 'oraculo.tsk061.admin@example.invalid',
                 'oraculo.tsk061.admin', 'ADMINISTRADOR', 'ACTIVO',
                 'hash-oraculo-tsk061-admin', 'argon2id')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_at, created_by)
         VALUES (c_empleado_nom, 'oraculo.tsk061.empleado@example.invalid',
                 'oraculo.tsk061.empleado', 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk061-empleado', 'argon2id', v_t0, v_admin)
      RETURNING user_id INTO v_empleado;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_at, created_by)
         VALUES (c_tecnico_nom, 'oraculo.tsk061.tecnico@example.invalid',
                 'oraculo.tsk061.tecnico', 'TECNICO_MANTENIMIENTO', 'ACTIVO',
                 'hash-oraculo-tsk061-tecnico', 'argon2id', v_t0, v_admin)
      RETURNING user_id INTO v_tecnico;

    v_oficina   := oficina_oraculo;
    v_sala      := sala_oraculo(v_oficina, v_admin);
    v_categoria := categoria_oraculo;

    -- ESCENARIO A: historico COHERENTE, ciclo completo ABIERTA, EN_CURSO, RESUELTA, CERRADA.
    v_inc_a := alta_incidencia('INC-ORA61-000001', v_empleado, v_t0);

    v_h0 := huella('ORA61|A|0');
    asentar(v_inc_a, 'CREACION', NULL, 'ABIERTA', NULL, NULL,
            v_empleado, c_empleado_nom, v_t0, NULL, NULL, v_h0);

    UPDATE incidencia
       SET assigned_technician_id = v_tecnico, assigned_at = v_t1, updated_at = v_t1
     WHERE incident_id = v_inc_a;
    v_h1 := huella('ORA61|A|1');
    asentar(v_inc_a, 'ASIGNACION', 'ABIERTA', 'ABIERTA', v_tecnico, c_tecnico_nom,
            v_admin, c_admin_nom, v_t1, NULL, v_h0, v_h1);

    UPDATE incidencia
       SET status = 'EN_CURSO', in_progress_at = v_t2,
           status_changed_at = v_t2, status_changed_by = v_tecnico, updated_at = v_t2
     WHERE incident_id = v_inc_a;
    v_h2 := huella('ORA61|A|2');
    asentar(v_inc_a, 'CAMBIO_ESTADO', 'ABIERTA', 'EN_CURSO', NULL, NULL,
            v_tecnico, c_tecnico_nom, v_t2, NULL, v_h1, v_h2);

    UPDATE incidencia
       SET status = 'RESUELTA', resolved_at = v_t3,
           status_changed_at = v_t3, status_changed_by = v_tecnico, updated_at = v_t3
     WHERE incident_id = v_inc_a;
    v_h3 := huella('ORA61|A|3');
    asentar(v_inc_a, 'CAMBIO_ESTADO', 'EN_CURSO', 'RESUELTA', NULL, NULL,
            v_tecnico, c_tecnico_nom, v_t3, NULL, v_h2, v_h3);

    UPDATE incidencia
       SET status = 'CERRADA', closed_at = v_t4, closed_by = v_admin,
           resolution_comment = c_resolucion,
           status_changed_at = v_t4, status_changed_by = v_admin, updated_at = v_t4
     WHERE incident_id = v_inc_a;
    v_h4 := huella('ORA61|A|4');
    asentar(v_inc_a, 'CAMBIO_ESTADO', 'RESUELTA', 'CERRADA', NULL, NULL,
            v_admin, c_admin_nom, v_t4, v_inc_a, v_h3, v_h4);

    exigir('v_chk_incidencia_sin_alta',  v_inc_a, 0, -20700, 'escenario A coherente');
    exigir('v_chk_estado_desalineado',   v_inc_a, 0, -20700, 'escenario A coherente');
    exigir('v_chk_cadena_hash',          v_inc_a, 0, -20700, 'escenario A coherente');
    exigir('v_chk_cierre_1a1',           v_inc_a, 0, -20700, 'escenario A coherente');

    -- ESCENARIO B: el historico avanza a EN_CURSO pero la incidencia se queda en ABIERTA.
    v_inc_b := alta_incidencia('INC-ORA61-000002', v_empleado, v_t0);

    v_h0 := huella('ORA61|B|0');
    asentar(v_inc_b, 'CREACION', NULL, 'ABIERTA', NULL, NULL,
            v_empleado, c_empleado_nom, v_t0, NULL, NULL, v_h0);

    v_h1 := huella('ORA61|B|1');
    asentar(v_inc_b, 'CAMBIO_ESTADO', 'ABIERTA', 'EN_CURSO', NULL, NULL,
            v_tecnico, c_tecnico_nom, v_t1, NULL, v_h0, v_h1);

    exigir('v_chk_estado_desalineado',   v_inc_b, 1, -20701, 'escenario B desalineado');
    exigir('v_chk_incidencia_sin_alta',  v_inc_b, 0, -20701, 'escenario B desalineado');
    exigir('v_chk_cadena_hash',          v_inc_b, 0, -20701, 'escenario B desalineado');
    exigir('v_chk_cierre_1a1',           v_inc_b, 0, -20701, 'escenario B desalineado');

    -- La verificacion es SOLO DIAGNOSTICA: consultar las vistas no ha tocado ni un dato.
    SELECT COUNT(*) INTO v_asientos FROM incidencia_historico WHERE incident_id = v_inc_b;
    SELECT status   INTO v_estado   FROM incidencia           WHERE incident_id = v_inc_b;
    IF v_asientos <> 2 OR v_estado <> 'ABIERTA' THEN
        RAISE_APPLICATION_ERROR(-20704, 'ORACULO REQ-152 RN-01: la verificacion ha alterado el historico; quedan ' ||
            v_asientos || ' asientos y el estado es ' || v_estado);
    END IF;

    -- ESCENARIO C: cadena de huellas rota, con el estado alineado para aislar la regla.
    v_inc_c := alta_incidencia('INC-ORA61-000003', v_empleado, v_t0);

    v_h0 := huella('ORA61|C|0');
    asentar(v_inc_c, 'CREACION', NULL, 'ABIERTA', NULL, NULL,
            v_empleado, c_empleado_nom, v_t0, NULL, NULL, v_h0);

    UPDATE incidencia
       SET status = 'EN_CURSO', in_progress_at = v_t1,
           status_changed_at = v_t1, status_changed_by = v_tecnico, updated_at = v_t1
     WHERE incident_id = v_inc_c;

    v_falsa := huella('ORA61|C|huella-manipulada');
    v_h1    := huella('ORA61|C|1');
    asentar(v_inc_c, 'CAMBIO_ESTADO', 'ABIERTA', 'EN_CURSO', NULL, NULL,
            v_tecnico, c_tecnico_nom, v_t1, NULL, v_falsa, v_h1);

    exigir('v_chk_cadena_hash',          v_inc_c, 1, -20702, 'escenario C cadena rota');
    exigir('v_chk_incidencia_sin_alta',  v_inc_c, 0, -20702, 'escenario C cadena rota');
    exigir('v_chk_estado_desalineado',   v_inc_c, 0, -20702, 'escenario C cadena rota');
    exigir('v_chk_cierre_1a1',           v_inc_c, 0, -20702, 'escenario C cadena rota');

    -- ESCENARIO D: incidencia sin entrada de alta en el historico.
    v_inc_d := alta_incidencia('INC-ORA61-000004', v_empleado, v_t0);

    exigir('v_chk_incidencia_sin_alta',  v_inc_d, 1, -20703, 'escenario D sin alta');
    exigir('v_chk_estado_desalineado',   v_inc_d, 0, -20703, 'escenario D sin alta');
    exigir('v_chk_cadena_hash',          v_inc_d, 0, -20703, 'escenario D sin alta');
    exigir('v_chk_cierre_1a1',           v_inc_d, 0, -20703, 'escenario D sin alta');

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin     NUMBER;
    v_oficina   NUMBER;
    v_sala      NUMBER;
    v_categoria NUMBER;
    v_inc       NUMBER;
    v_rep1      NUMBER;
    v_rep2      NUMBER;
    v_hallazgo  NUMBER;
    v_sqlcode   NUMBER;
    v_estado    VARCHAR2(20 CHAR);
    v_now       TIMESTAMP := SYS_EXTRACT_UTC(SYSTIMESTAMP);

    c_admin_nom   CONSTANT VARCHAR2(150 CHAR) := 'Oraculo TSK-061 Integridad Administrador';
    c_descripcion CONSTANT VARCHAR2(500 CHAR) := 'Incidencia del oraculo TSK-061 usada como sujeto de un hallazgo de integridad';

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER, p_terminal VARCHAR2) IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, p_terminal, 'Y');
    END sembrar_estado;

    FUNCTION oficina_oraculo RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT office_id INTO l_id FROM cat_oficina WHERE office_code = 'ORA61';
        UPDATE cat_oficina SET is_active = 'Y' WHERE office_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_oficina (office_code, office_name, city, is_active)
                 VALUES ('ORA61', 'Oficina del oraculo TSK-061', 'Madrid', 'Y')
              RETURNING office_id INTO l_id;
            RETURN l_id;
    END oficina_oraculo;

    FUNCTION sala_oraculo(p_office_id NUMBER, p_created_by NUMBER) RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT room_id INTO l_id FROM cat_sala WHERE room_code = 'ORA61-SALA-01';
        UPDATE cat_sala SET is_active = 'Y' WHERE room_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_sala (room_code, room_name, office_id, is_active, created_by)
                 VALUES ('ORA61-SALA-01', 'Sala del oraculo TSK-061', p_office_id, 'Y', p_created_by)
              RETURNING room_id INTO l_id;
            RETURN l_id;
    END sala_oraculo;

    FUNCTION categoria_oraculo RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT category_id INTO l_id FROM cat_categoria_incidencia WHERE category_code = 'CLIMATIZACION';
        UPDATE cat_categoria_incidencia SET is_active = 'Y' WHERE category_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_categoria_incidencia (category_code, category_name, display_order, is_active)
                 VALUES ('CLIMATIZACION', 'Climatizacion oraculo TSK-061', 961, 'Y')
              RETURNING category_id INTO l_id;
            RETURN l_id;
    END categoria_oraculo;
BEGIN
    sembrar_rol('ADMINISTRADOR', 'Administrador', 913);
    sembrar_estado('ABIERTA', 'Abierta', 1, 'N');

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES (c_admin_nom, 'oraculo.tsk061.integridad@example.invalid',
                 'oraculo.tsk061.integridad', 'ADMINISTRADOR', 'ACTIVO',
                 'hash-oraculo-tsk061-integridad', 'argon2id')
      RETURNING user_id INTO v_admin;

    v_oficina   := oficina_oraculo;
    v_sala      := sala_oraculo(v_oficina, v_admin);
    v_categoria := categoria_oraculo;

    INSERT INTO incidencia (reference_code, room_id, category_id,
                            room_name_snapshot, office_name_snapshot, category_name_snapshot,
                            description, status, reported_by, created_at, status_changed_at)
         VALUES ('INC-ORA61-000011', v_sala, v_categoria,
                 'Sala del oraculo TSK-061', 'Oficina del oraculo TSK-061', 'Climatizacion oraculo TSK-061',
                 c_descripcion, 'ABIERTA', v_admin, v_now - INTERVAL '1' HOUR, v_now - INTERVAL '1' HOUR)
      RETURNING incident_id INTO v_inc;

    -- (1) El ADMINISTRADOR lanza una verificacion acotada a los ultimos doce meses.
    INSERT INTO integridad_informe (executed_by, scope_date_from, scope_date_to, status)
         VALUES (v_admin, ADD_MONTHS(TRUNC(SYSDATE), -12), TRUNC(SYSDATE), 'EN_CURSO')
      RETURNING integrity_report_id INTO v_rep1;

    -- (2) AC-HIST-07: una segunda verificacion simultanea choca contra el indice unico.
    BEGIN
        INSERT INTO integridad_informe (executed_by, status)
             VALUES (v_admin, 'EN_CURSO')
          RETURNING integrity_report_id INTO v_rep2;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -1 THEN
        RAISE_APPLICATION_ERROR(-20710, 'ORACULO AC-HIST-07: una segunda verificacion simultanea deberia chocar con ORA-00001 y el SQLCODE obtenido ha sido ' || v_sqlcode);
    END IF;

    -- (3) El informe en curso registra sus hallazgos: solo identificadores y regla incumplida.
    INSERT INTO integridad_hallazgo (integrity_report_id, incident_id, rule_code, finding_detail)
         VALUES (v_rep1, v_inc, 'estado_desalineado',
                 'El estado vigente de la incidencia ' || v_inc || ' no coincide con el to_status de su ultima entrada de historico')
      RETURNING finding_id INTO v_hallazgo;

    -- (4) Una regla fuera del enumerado de REQ-152 la rechaza la base de datos.
    BEGIN
        INSERT INTO integridad_hallazgo (integrity_report_id, incident_id, rule_code)
             VALUES (v_rep1, v_inc, 'regla_inventada');
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -2290 THEN
        RAISE_APPLICATION_ERROR(-20711, 'ORACULO REQ-152: un rule_code fuera del enumerado deberia violar ck_integridad_hallazgo_rule y el SQLCODE obtenido ha sido ' || v_sqlcode);
    END IF;

    -- (5) Un hallazgo es append-only puro: ni se corrige ni se borra.
    BEGIN
        UPDATE integridad_hallazgo SET rule_code = 'sin_alta' WHERE finding_id = v_hallazgo;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -20006 THEN
        RAISE_APPLICATION_ERROR(-20712, 'ORACULO REQ-152 RN-09: modificar un hallazgo deberia fallar con ORA-20006 y el SQLCODE obtenido ha sido ' || v_sqlcode);
    END IF;

    BEGIN
        DELETE FROM integridad_hallazgo WHERE finding_id = v_hallazgo;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -20006 THEN
        RAISE_APPLICATION_ERROR(-20713, 'ORACULO REQ-152 RN-09: borrar un hallazgo deberia fallar con ORA-20006 y el SQLCODE obtenido ha sido ' || v_sqlcode);
    END IF;

    -- (6) El sellado del informe es el UNICO cambio admitido sobre una ejecucion en curso.
    UPDATE integridad_informe
       SET status = 'COMPLETADO', checked_count = 4, inconsistency_count = 1
     WHERE integrity_report_id = v_rep1;

    SELECT status INTO v_estado FROM integridad_informe WHERE integrity_report_id = v_rep1;
    IF v_estado <> 'COMPLETADO' THEN
        RAISE_APPLICATION_ERROR(-20714, 'ORACULO REQ-152: el sellado del informe deberia dejarlo COMPLETADO y ha quedado ' || v_estado);
    END IF;

    -- (7) Sellada la primera, ya cabe una nueva ejecucion, y esta es PROGRAMADA (sin actor).
    INSERT INTO integridad_informe (executed_by, status)
         VALUES (NULL, 'EN_CURSO')
      RETURNING integrity_report_id INTO v_rep2;

    -- (8) Un informe ya sellado es inmutable, igual que el resto del historico.
    BEGIN
        UPDATE integridad_informe SET inconsistency_count = 0 WHERE integrity_report_id = v_rep1;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -20007 THEN
        RAISE_APPLICATION_ERROR(-20715, 'ORACULO REQ-152 RN-09: modificar un informe sellado deberia fallar con ORA-20007 y el SQLCODE obtenido ha sido ' || v_sqlcode);
    END IF;

    BEGIN
        DELETE FROM integridad_informe WHERE integrity_report_id = v_rep1;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -20007 THEN
        RAISE_APPLICATION_ERROR(-20716, 'ORACULO REQ-047: borrar un informe de integridad deberia fallar con ORA-20007 y el SQLCODE obtenido ha sido ' || v_sqlcode);
    END IF;

    -- (9) Las dos validaciones de alcance de REQ-152 las impone la BASE DE DATOS.
    BEGIN
        INSERT INTO integridad_informe (executed_by, scope_date_from, scope_date_to, status)
             VALUES (v_admin, TRUNC(SYSDATE), ADD_MONTHS(TRUNC(SYSDATE), -1), 'COMPLETADO');
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -2290 THEN
        RAISE_APPLICATION_ERROR(-20717, 'ORACULO REQ-152: un rango con la fecha inicial posterior a la final deberia violar ck_integridad_informe_rango y el SQLCODE obtenido ha sido ' || v_sqlcode);
    END IF;

    BEGIN
        INSERT INTO integridad_informe (executed_by, scope_date_from, scope_date_to, status)
             VALUES (v_admin, ADD_MONTHS(TRUNC(SYSDATE), -36), TRUNC(SYSDATE), 'COMPLETADO');
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    IF v_sqlcode <> -2290 THEN
        RAISE_APPLICATION_ERROR(-20718, 'ORACULO REQ-152: un rango de 36 meses deberia violar ck_integridad_informe_ventana y el SQLCODE obtenido ha sido ' || v_sqlcode);
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin      NUMBER;
    v_usuario    NUMBER;
    v_oficina    NUMBER;
    v_sala       NUMBER;
    v_categoria  NUMBER;
    v_inc        NUMBER;
    v_aviso      VARCHAR2(36 CHAR);
    v_audit      VARCHAR2(36 CHAR);
    v_hash       VARCHAR2(64 CHAR);
    v_leido      VARCHAR2(64 CHAR);
    v_n          NUMBER;
    v_sqlcode    NUMBER;
    v_viejo      TIMESTAMP;
    v_corte      TIMESTAMP;

    c_admin_nom   CONSTANT VARCHAR2(150 CHAR) := 'Oraculo TSK-061 Retencion Administrador';
    c_usuario_nom CONSTANT VARCHAR2(150 CHAR) := 'Oraculo TSK-061 Retencion Empleado';
    c_descripcion CONSTANT VARCHAR2(500 CHAR) := 'Incidencia del oraculo TSK-061 fechada 23 meses atras para verificar la ventana de retencion';
    c_pwd_hash    CONSTANT VARCHAR2(255 CHAR) := 'hash-oraculo-tsk061-retencion-anterior';

    FUNCTION uuid RETURN VARCHAR2 IS
        l_uuid VARCHAR2(36 CHAR);
    BEGIN
        SELECT LOWER(REGEXP_REPLACE(RAWTOHEX(SYS_GUID()), '(.{8})(.{4})(.{4})(.{4})(.{12})', '\1-\2-\3-\4-\5'))
          INTO l_uuid FROM dual;
        RETURN l_uuid;
    END uuid;

    FUNCTION huella(p_semilla VARCHAR2) RETURN VARCHAR2 IS
        l_hash VARCHAR2(64 CHAR);
    BEGIN
        SELECT RAWTOHEX(STANDARD_HASH(p_semilla, 'SHA256')) INTO l_hash FROM dual;
        RETURN l_hash;
    END huella;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER, p_terminal VARCHAR2) IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, p_terminal, 'Y');
    END sembrar_estado;

    FUNCTION oficina_oraculo RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT office_id INTO l_id FROM cat_oficina WHERE office_code = 'ORA61';
        UPDATE cat_oficina SET is_active = 'Y' WHERE office_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_oficina (office_code, office_name, city, is_active)
                 VALUES ('ORA61', 'Oficina del oraculo TSK-061', 'Madrid', 'Y')
              RETURNING office_id INTO l_id;
            RETURN l_id;
    END oficina_oraculo;

    FUNCTION sala_oraculo(p_office_id NUMBER, p_created_by NUMBER) RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT room_id INTO l_id FROM cat_sala WHERE room_code = 'ORA61-SALA-01';
        UPDATE cat_sala SET is_active = 'Y' WHERE room_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_sala (room_code, room_name, office_id, is_active, created_by)
                 VALUES ('ORA61-SALA-01', 'Sala del oraculo TSK-061', p_office_id, 'Y', p_created_by)
              RETURNING room_id INTO l_id;
            RETURN l_id;
    END sala_oraculo;

    FUNCTION categoria_oraculo RETURN NUMBER IS
        l_id NUMBER;
    BEGIN
        SELECT category_id INTO l_id FROM cat_categoria_incidencia WHERE category_code = 'CLIMATIZACION';
        UPDATE cat_categoria_incidencia SET is_active = 'Y' WHERE category_id = l_id AND is_active <> 'Y';
        RETURN l_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO cat_categoria_incidencia (category_code, category_name, display_order, is_active)
                 VALUES ('CLIMATIZACION', 'Climatizacion oraculo TSK-061', 961, 'Y')
              RETURNING category_id INTO l_id;
            RETURN l_id;
    END categoria_oraculo;

    PROCEDURE exigir_una(p_filas NUMBER, p_codigo NUMBER, p_tabla VARCHAR2) IS
    BEGIN
        IF p_filas <> 1 THEN
            RAISE_APPLICATION_ERROR(p_codigo, 'ORACULO AC-G-07 / AC-TRZ-04: la tabla ' || p_tabla ||
                ' deberia conservar 1 registro de 23 meses de antiguedad intacto y consultable, y devuelve ' || p_filas);
        END IF;
    END exigir_una;

    PROCEDURE exigir_sqlcode(p_obtenido NUMBER, p_esperado NUMBER, p_codigo NUMBER, p_caso VARCHAR2) IS
    BEGIN
        IF p_obtenido <> p_esperado THEN
            RAISE_APPLICATION_ERROR(p_codigo, 'ORACULO REQ-047: ' || p_caso || ' deberia fallar con SQLCODE ' ||
                p_esperado || ' y el obtenido ha sido ' || p_obtenido);
        END IF;
    END exigir_sqlcode;
BEGIN
    v_viejo := CAST(ADD_MONTHS(CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS DATE), -23) AS TIMESTAMP);
    v_corte := CAST(ADD_MONTHS(CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS DATE), -22) AS TIMESTAMP);

    sembrar_rol('EMPLEADO', 'Empleado', 911);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 913);
    sembrar_estado('ABIERTA', 'Abierta', 1, 'N');

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES (c_admin_nom, 'oraculo.tsk061.retencion.admin@example.invalid',
                 'oraculo.tsk061.retencion.admin', 'ADMINISTRADOR', 'ACTIVO',
                 'hash-oraculo-tsk061-retencion-admin', 'argon2id')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_at, created_by)
         VALUES (c_usuario_nom, 'oraculo.tsk061.retencion@example.invalid',
                 'oraculo.tsk061.retencion', 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk061-retencion', 'argon2id', v_viejo, v_admin)
      RETURNING user_id INTO v_usuario;

    v_oficina   := oficina_oraculo;
    v_sala      := sala_oraculo(v_oficina, v_admin);
    v_categoria := categoria_oraculo;

    INSERT INTO incidencia (reference_code, room_id, category_id,
                            room_name_snapshot, office_name_snapshot, category_name_snapshot,
                            description, status, reported_by, created_at, status_changed_at)
         VALUES ('INC-ORA61-000021', v_sala, v_categoria,
                 'Sala del oraculo TSK-061', 'Oficina del oraculo TSK-061', 'Climatizacion oraculo TSK-061',
                 c_descripcion, 'ABIERTA', v_usuario, v_viejo, v_viejo)
      RETURNING incident_id INTO v_inc;

    -- (1) incidencia_historico: asiento de alta de hace 23 meses.
    v_hash := huella('ORA61|RETENCION|0');
    INSERT INTO incidencia_historico (incident_id, entry_type, from_status, to_status,
                                      actor_user_id, actor_display_name, changed_at,
                                      previous_entry_hash, entry_hash)
         VALUES (v_inc, 'CREACION', NULL, 'ABIERTA',
                 v_usuario, c_usuario_nom, v_viejo,
                 NULL, v_hash);

    -- (2) usuario_historico: asiento de alta de la cuenta, de hace 23 meses.
    INSERT INTO usuario_historico (user_id, change_type, new_status, changed_by, valid_from, changed_at)
         VALUES (v_usuario, 'ESTADO', 'ACTIVO', v_admin, v_viejo, v_viejo);

    -- (3) usuario_password_historico: contrasenia anterior retirada hace 23 meses.
    INSERT INTO usuario_password_historico (user_id, password_hash, created_at)
         VALUES (v_usuario, c_pwd_hash, v_viejo);

    -- (4) auditoria_acceso: trg_auditoria_acceso_servidor sella occurred_at con la hora del
    --     servidor, de modo que esta entrada NO puede fecharse 23 meses atras. Lo que se verifica
    --     mas abajo es su ventana de retencion declarada y su inmutabilidad.
    INSERT INTO auditoria_acceso (user_id, event_type, outcome, operation)
         VALUES (v_usuario, 'login_ok', 'OK', 'ORACULO-TSK-061')
      RETURNING audit_id INTO v_audit;

    -- (5) aviso_correo y (6) aviso_correo_intento: entrega registrada hace 23 meses.
    v_aviso := uuid;
    INSERT INTO aviso_correo (notification_id, notification_key, notification_type,
                              recipient_user_id, recipient_email, subject, status, created_at)
         VALUES (v_aviso, 'ORACULO-TSK-061-RETENCION-' || v_usuario, 'CREDENTIAL_ISSUED',
                 v_usuario, 'oraculo.tsk061.retencion@example.invalid',
                 'Credenciales de acceso', 'PENDIENTE', v_viejo);

    INSERT INTO aviso_correo_intento (attempt_id, notification_id, attempt_number, attempted_at,
                                      result_code, recipient_count, message_id)
         VALUES (uuid, v_aviso, 1, v_viejo,
                 'SENT', 1, 'oraculo-tsk061-retencion@example.invalid');

    -- (7) resolucion_destinatario_log: resolucion de destinatarios de hace 23 meses.
    INSERT INTO resolucion_destinatario_log (request_type, requested_by_module, subject_user_id,
                                             resolved_user_ids, recipient_count, is_fallback_used,
                                             outcome, resolved_at)
         VALUES ('INDIVIDUAL', 'ORACULO-TSK-061', v_usuario,
                 '[' || v_usuario || ']', 1, 'N',
                 'OK', v_viejo);

    -- ------------------------------------------------------------------------------
    -- AC-G-07 / AC-TRZ-04: los registros de 23 meses siguen ahi, intactos y legibles
    -- ------------------------------------------------------------------------------
    SELECT COUNT(*) INTO v_n FROM incidencia
     WHERE incident_id = v_inc AND created_at <= v_corte;
    exigir_una(v_n, -20720, 'incidencia');

    SELECT COUNT(*) INTO v_n FROM incidencia_historico
     WHERE incident_id = v_inc AND changed_at <= v_corte;
    exigir_una(v_n, -20721, 'incidencia_historico');

    SELECT COUNT(*) INTO v_n FROM usuario_historico
     WHERE user_id = v_usuario AND changed_at <= v_corte;
    exigir_una(v_n, -20722, 'usuario_historico');

    SELECT COUNT(*) INTO v_n FROM usuario_password_historico
     WHERE user_id = v_usuario AND created_at <= v_corte;
    exigir_una(v_n, -20723, 'usuario_password_historico');

    SELECT COUNT(*) INTO v_n FROM aviso_correo_intento
     WHERE notification_id = v_aviso AND attempted_at <= v_corte;
    exigir_una(v_n, -20724, 'aviso_correo_intento');

    SELECT COUNT(*) INTO v_n FROM resolucion_destinatario_log
     WHERE subject_user_id = v_usuario AND resolved_at <= v_corte;
    exigir_una(v_n, -20725, 'resolucion_destinatario_log');

    -- auditoria_acceso: entrada consultable y con una ventana de retencion que cubre 23 meses.
    SELECT COUNT(*) INTO v_n FROM auditoria_acceso
     WHERE audit_id = v_audit AND retention_until >= ADD_MONTHS(TRUNC(SYSDATE), 23);
    exigir_una(v_n, -20726, 'auditoria_acceso');

    -- El contenido no ha sido alterado: la huella almacenada es la que se escribio.
    SELECT entry_hash INTO v_leido FROM incidencia_historico WHERE incident_id = v_inc;
    IF v_leido <> v_hash THEN
        RAISE_APPLICATION_ERROR(-20727, 'ORACULO AC-TRZ-04: el entry_hash del asiento de 23 meses ha cambiado');
    END IF;

    SELECT COUNT(*) INTO v_n FROM usuario_password_historico
     WHERE user_id = v_usuario AND password_hash = c_pwd_hash;
    exigir_una(v_n, -20728, 'usuario_password_historico (contenido intacto)');

    -- ------------------------------------------------------------------
    -- AC-G-09: el esquema no declara ningun job programado de purga
    -- ------------------------------------------------------------------
    SELECT COUNT(*) INTO v_n FROM user_scheduler_jobs;
    IF v_n <> 0 THEN
        RAISE_APPLICATION_ERROR(-20730, 'ORACULO AC-G-09: el esquema declara ' || v_n ||
            ' jobs programados y no debe existir ninguna purga automatica de datos');
    END IF;

    -- ------------------------------------------------------------------
    -- REQ-047: sin borrado fisico, ni siquiera para el dueno del esquema
    -- ------------------------------------------------------------------
    BEGIN
        DELETE FROM incidencia_historico WHERE incident_id = v_inc;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    exigir_sqlcode(v_sqlcode, -20002, -20731, 'borrar una entrada de incidencia_historico');

    BEGIN
        DELETE FROM auditoria_acceso WHERE audit_id = v_audit;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    exigir_sqlcode(v_sqlcode, -20003, -20732, 'borrar una entrada de auditoria_acceso');

    BEGIN
        DELETE FROM usuario_historico WHERE user_id = v_usuario;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    exigir_sqlcode(v_sqlcode, -20001, -20733, 'borrar una entrada de usuario_historico');

    BEGIN
        DELETE FROM aviso_correo_intento WHERE notification_id = v_aviso;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    exigir_sqlcode(v_sqlcode, -20004, -20734, 'borrar una entrada de aviso_correo_intento');

    BEGIN
        DELETE FROM resolucion_destinatario_log WHERE subject_user_id = v_usuario;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    exigir_sqlcode(v_sqlcode, -20005, -20735, 'borrar una entrada de resolucion_destinatario_log');

    BEGIN
        DELETE FROM usuario WHERE user_id = v_usuario;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;
    exigir_sqlcode(v_sqlcode, -2292, -20736, 'borrar fisicamente un usuario con historico');

    -- La unica eliminacion automatica del esquema acota a tres las contrasenias anteriores por
    -- usuario (reutilizacion), no purga por antiguedad: la entrada de 23 meses sigue ahi.
    SELECT COUNT(*) INTO v_n FROM usuario_password_historico
     WHERE user_id = v_usuario AND created_at <= v_corte;
    exigir_una(v_n, -20737, 'usuario_password_historico (supervivencia final)');

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
